async def is_member(user_id, context):
    try:
        channel = await context.bot.get_chat_member(CHANNEL_USERNAME, user_id)
        group = await context.bot.get_chat_member(GROUP_USERNAME, user_id)

        allowed = {"member", "administrator", "creator"}

        return (
            channel.status in allowed
            and group.status in allowed
        )

    except Exception as error:
        print("JOIN CHECK ERROR:", error)
        return False


async def force_join_message(message):
    keyboard = [
        [InlineKeyboardButton("📢 Join Channel", url=CHANNEL_URL)],
        [InlineKeyboardButton("👥 Join Group", url=GROUP_URL)],
        [InlineKeyboardButton("✅ I Have Joined", callback_data="verify_join")],
    ]

    await message.reply_text(
        "🔐 Join Required\n\n"
        "NEET Study Hub use karne ke liye pehle hamara "
        "Channel aur Group join karo.\n\n"
        "1️⃣ Channel join karo\n"
        "2️⃣ Group join karo\n"
        "3️⃣ I Have Joined dabao 👇",
        reply_markup=InlineKeyboardMarkup(keyboard),
    )


