async def chapter_menu(query, class_number, subject):
    chapters = load_chapters()
    chapter_list = chapters.get(str(class_number), {}).get(subject, [])

    if not chapter_list:
        await edit_text(
            query.message,
            "⚠️ Is class ke chapters available nahi hain.",
            back_home_keyboard(f"subject_{subject}"),
        )
        return

    keyboard = []

    for index, chapter in enumerate(chapter_list):
        keyboard.append([
            InlineKeyboardButton(
                f"📖 {chapter}",
                callback_data=f"chapter|{class_number}|{subject}|{index}",
            )
        ])

    keyboard.append([
        InlineKeyboardButton(
            "🔙 Back",
            callback_data=f"subject_{subject}",
        ),
        InlineKeyboardButton("🏠 Home", callback_data="home"),
    ])

    await edit_text(
        query.message,
        f"📚 Class {class_number} {subject}\n\nChapter choose karo 👇",
        InlineKeyboardMarkup(keyboard),
    )


# =========================================================
# QUESTIONS
# =========================================================

async def start_question(query, class_number, subject, chapter_index):
    chapters = load_chapters()
    chapter = (
        chapters.get(str(class_number), {})
        .get(subject, [])[chapter_index]
    )

    questions = load_questions()

    matching = [
        q for q in questions
        if str(q.get("class")) == str(class_number)
        and q.get("subject") == subject
        and q.get("chapter") == chapter
    ]

    if not matching:
        await edit_text(
            query.message,
            "📚 Is chapter ke questions abhi add nahi hue.",
            back_home_keyboard(
                f"class_{class_number}_{subject}"
            ),
        )
        return

    question = random.choice(matching)

    # Context is stored by the handler before calling this function.
    return await show_question(
        query,
        class_number,
        subject,
        chapter_index,
        question,
    )


async def show_question(
    query,
    class_number,
    subject,
    chapter_index,
    question,
):
    keyboard = []

    for index, option in enumerate(question["options"]):
        keyboard.append([
            InlineKeyboardButton(
                f"{chr(65 + index)}) {option}",
                callback_data=f"answer|{question['id']}|{index}",
            )
        ])

    keyboard.append([
        InlineKeyboardButton(
            "🔙 Back",
            callback_data=f"chapters|{class_number}|{subject}",
        ),
        InlineKeyboardButton("🏠 Home", callback_data="home"),
    ])

    text = (
        f"🔥 {question.get('difficulty', 'NEET Level')}\n\n"
        f"🧠 {question['question']}\n\n"
        "Answer choose karo 👇"
    )

    await edit_text(
        query.message,
        text,
        InlineKeyboardMarkup(keyboard),
    )


async def answer_question(query, context, question_id, option_index):
    questions = load_questions()

    question = next(
        (q for q in questions if str(q["id"]) == str(question_id)),
        None,
    )

    if not question:
        await query.answer("Question nahi mila.", show_alert=True)
        return

    try:
        selected = question["options"][option_index]
    except (IndexError, TypeError):
        await query.answer("Invalid option.", show_alert=True)
        return

    correct = selected == question["answer"]
    update_score(query.from_user.id, correct)

    if correct:
        result = "✅ Correct Answer!"
    else:
        result = f"❌ Wrong Answer!\n\n✅ Correct: {question['answer']}"

    text = (
        f"{result}\n\n"
        "💡 Explanation:\n"
        f"{question.get('explanation', 'Explanation unavailable.')}"
    )

    ctx = context.user_data.get("question_context")
    if not ctx:
        keyboard = [[
            InlineKeyboardButton("📚 Practice", callback_data="practice"),
            InlineKeyboardButton("🏠 Home", callback_data="home"),
        ]]
    else:
        class_number, subject, chapter_index = ctx
        keyboard = [
            [
                InlineKeyboardButton(
                    "🔄 Next Question",
                    callback_data=f"next|{class_number}|{subject}|{chapter_index}",
                )
            ],
            [
                InlineKeyboardButton(
                    "🔙 Chapter",
                    callback_data=f"chapters|{class_number}|{subject}",
                ),
                InlineKeyboardButton("🏠 Home", callback_data="home"),
            ],
        ]

    await edit_text(
        query.message,
        text,
        InlineKeyboardMarkup(keyboard),
    )


