async def ai_doubt_start(query, context):
    context.user_data["waiting_for_ai"] = True

    await edit_text(
        query.message,
        "🤖 AI Doubt Solver\n\n"
        "Apna NEET doubt message mein bhejo.\n\n"
        "Example:\n"
        "Why does increasing temperature affect equilibrium?\n\n"
        "❌ /cancel se AI mode band kar sakte ho.",
        back_home_keyboard("home"),
    )


async def ai_message(update, context):
    if not context.user_data.get("waiting_for_ai", False):
        return

    user = update.effective_user

    if not await is_member(user.id, context):
        context.user_data["waiting_for_ai"] = False
        await force_join_message(update.message)
        return

    question = (update.message.text or "").strip()

    if question == "/cancel":
        context.user_data["waiting_for_ai"] = False
        await update.message.reply_text(
            "❌ AI mode closed.",
            reply_markup=home_keyboard(),
        )
        return

    if not question:
        await update.message.reply_text("⚠️ Apna doubt text mein bhejo.")
        return

    context.user_data["waiting_for_ai"] = False

    waiting = await update.message.reply_text("🤔 Doubt solve kar raha hoon...")

    try:
        answer = await asyncio.to_thread(ask_ai, question)

        keyboard = [
            [InlineKeyboardButton("🤖 Ask Another", callback_data="ai")],
            [InlineKeyboardButton("🔙 Back", callback_data="home"),
             InlineKeyboardButton("🏠 Home", callback_data="home")],
        ]

        await waiting.edit_text(
            "🤖 AI Answer\n\n" + answer,
            reply_markup=InlineKeyboardMarkup(keyboard),
        )

    except Exception as error:
        print("AI ERROR:", error)

        await waiting.edit_text(
            "⚠️ AI service abhi available nahi hai.",
            reply_markup=InlineKeyboardMarkup([
                [InlineKeyboardButton("🤖 Try Again", callback_data="ai")],
                [InlineKeyboardButton("🏠 Home", callback_data="home")],
            ]),
        )


