def donation_image():
    return BytesIO(base64.b64decode(DONATION_QR_B64))


async def show_support(query):
    caption = (
        "❤️ Support NEET Study Hub 2027\n\n"
        "Agar bot aapke NEET preparation mein useful hai, "
        "to aap voluntarily support kar sakte ho. 🙏\n\n"
        f"💳 UPI ID: `{UPI_ID}`\n"
        f"👤 Name: {UPI_NAME}\n\n"
        "📱 QR scan karke payment kar sakte ho.\n"
        "Thank you for supporting the project ❤️"
    )

    keyboard = InlineKeyboardMarkup([
        [InlineKeyboardButton(
            "💳 Pay via UPI",
            url=f"upi://pay?pa={UPI_ID}&pn={UPI_NAME}",
        )],
        [
            InlineKeyboardButton("🔙 Back", callback_data="home"),
            InlineKeyboardButton("🏠 Home", callback_data="home"),
        ],
    ])

    # Telegram cannot turn a photo message back into a text message.
    # So the support screen is kept as the ONLY bot message: delete the
    # old menu message and create the donation photo message.
    try:
        await query.message.delete()
    except Exception as error:
        print("DONATION DELETE ERROR:", error)

    photo = donation_image()
    photo.name = "donation_qr.jpg"

    await query.message.chat.send_photo(
        photo=photo,
        caption=caption,
        parse_mode="Markdown",
        reply_markup=keyboard,
    )


