# =========================================================
# BUTTON HANDLER
# =========================================================

async def button_handler(update: Update, context: ContextTypes.DEFAULT_TYPE):
    query = update.callback_query
    await query.answer()

    data = query.data or ""

    # HOME
    if data == "home":
        context.user_data["waiting_for_ai"] = False

        # If Home is pressed from the donation photo, replace that photo
        # with a single fresh home message. All normal text screens remain
        # in the same Telegram message.
        if query.message.photo:
            try:
                await query.message.delete()
            except Exception as error:
                print("HOME DELETE ERROR:", error)
            await send_home(query.message)
        else:
            await show_home(query.message)
        return

    # VERIFY JOIN
    if data == "verify_join":
        if await is_member(query.from_user.id, context):
            context.user_data["waiting_for_ai"] = False
            await edit_text(
                query.message,
                "🎉 Verification Successful!\n\n"
                "Welcome to NEET Study Hub 2027 ❤️",
            )
            await show_home(query.message)
        else:
            await query.answer(
                "❌ Pehle Channel aur Group dono join karo!",
                show_alert=True,
            )
        return

    # PRACTICE
    if data == "practice":
        await practice_menu(query)
        return

    # SUBJECT
    if data.startswith("subject_"):
        subject = data.replace("subject_", "", 1)
        await class_menu(query, subject)
        return

    # CLASS
    if data.startswith("class_"):
        parts = data.split("_", 2)
        if len(parts) == 3:
            await chapter_menu(query, parts[1], parts[2])
        return

    # CHAPTER LIST BACK
    if data.startswith("chapters|"):
        parts = data.split("|", 2)
        if len(parts) == 3:
            await chapter_menu(query, parts[1], parts[2])
        return

    # CHAPTER -> QUESTION
    if data.startswith("chapter|"):
        parts = data.split("|")
        if len(parts) == 4:
            class_number = parts[1]
            subject = parts[2]
            chapter_index = int(parts[3])

            context.user_data["question_context"] = (
                class_number,
                subject,
                chapter_index,
            )

            await start_question(
                query,
                class_number,
                subject,
                chapter_index,
            )
        return

    # NEXT QUESTION
    if data.startswith("next|"):
        parts = data.split("|")
        if len(parts) == 4:
            class_number = parts[1]
            subject = parts[2]
            chapter_index = int(parts[3])

            context.user_data["question_context"] = (
                class_number,
                subject,
                chapter_index,
            )

            await start_question(
                query,
                class_number,
                subject,
                chapter_index,
            )
        return

    # ANSWER
    if data.startswith("answer|"):
        parts = data.split("|")
        if len(parts) == 3:
            await answer_question(
                query,
                context,
                parts[1],
                int(parts[2]),
            )
        return

    # AI
    if data == "ai":
        await ai_doubt_start(query, context)
        return

    # PROGRESS
    if data == "progress":
        await show_progress(query)
        return

    # LEADERBOARD
    if data == "leaderboard":
        await show_leaderboard(query)
        return

    # SUPPORT
    if data == "support":
        await show_support(query)
        return

    # FUTURE FEATURES
    if data == "pyq":
        await future_feature(query, "📝 NEET PYQ")
        return

    if data == "mock":
        await future_feature(query, "🎯 Mock Test")
        return

    if data == "biology":
        await future_feature(query, "🫀 3D Biology")
        return

    if data == "daily":
        await future_feature(query, "🔥 Daily Challenge")
        return


# =========================================================
# ERROR HANDLER
# =========================================================

async def error_handler(update, context):
    print("BOT ERROR:", context.error)


# =========================================================
# MAIN
# =========================================================

def main():
    if not BOT_TOKEN:
        raise ValueError("BOT_TOKEN missing!")

    init_database()

    application = (
        Application.builder()
        .token(BOT_TOKEN)
        .build()
    )

    application.add_handler(CommandHandler("start", start))

    application.add_handler(
        CallbackQueryHandler(button_handler)
    )

    application.add_handler(
        MessageHandler(
            filters.TEXT & ~filters.COMMAND,
            ai_message,
        )
    )

    application.add_error_handler(error_handler)

    print(f"{BOT_NAME} started...")

    application.run_polling(
        drop_pending_updates=True,
        allowed_updates=Update.ALL_TYPES,
    )


if __name__ == "__main__":
    main()
